input.new_string:
// Primary config loader.
const fs = require('fs');
function loadConfig() {
  const raw = fs.readFileSync('config.yaml', 'utf8');
  const result = {};
  for (const line of raw.split('\n')) {
    const m = line.match(/^(\w+):\s*(.+)$/);
    if (m) result[m[1]] = isNaN(m[2]) ? m[2] : Number(m[2]);
  }
  return result;
}
module.exports = { loadConfig };

